/**
 * ToggleGroup theme — a segmented control adapted from nuxt/ui v3.0.2
 * conventions (`button.ts` variant matrix + `button-group.ts` orientation
 * rounding). Each item renders a `ToggleGroupItem` styled like a button, with
 * `ui-on` flipping the active appearance per color × variant. Variants:
 * `outline`, `soft`, `subtle`. Dark rides the semantic tokens.
 */
import type { Color } from '@@vyui:theme/colors'
import { type IconFg, iconFgFromToken } from '@@vyui:theme/iconColor'

// Each builder returns the inactive + on-state surface classes (`base`)
// separately from the foreground color (`fg`, including the on-state shift). CSS
// inheritance is OFF in the Lynx build, so `fg` is spread onto the
// `leadingIcon` / `label` slots directly; the item <view> carries `group` +
// `data-state`, so the shift uses `group-ui-on:text-*` on the children.
const outline = (c: string) =>
  ({
    base: `border border-accented bg-default active:bg-${c}-50 active:bg-${c}-100`
      + ` ui-on:border-${c}-500 ui-on:bg-${c}-50`,
    fg: `text-default group-ui-on:text-${c}-600`,
  })

const soft = (c: string) =>
  ({
    base: `bg-elevated active:bg-${c}-50 active:bg-${c}-100`
      + ` ui-on:bg-${c}-100`,
    fg: `text-default group-ui-on:text-${c}-600`,
  })

const subtle = (c: string) =>
  ({
    base: `border border-default bg-default active:bg-${c}-50 active:bg-${c}-100`
      + ` ui-on:border-${c}-300 ui-on:bg-${c}-100`,
    fg: `text-default group-ui-on:text-${c}-600`,
  })

const VARIANT_BUILDERS = { outline, soft, subtle } as const

export type Variant = keyof typeof VARIANT_BUILDERS

const VARIANTS = Object.keys(VARIANT_BUILDERS) as Variant[]

// Same Lynx constraint as `button.ts`'s `iconFg`: the `<svg>` rasterizes its
// XML, so neither the resting `text-*` nor the `group-ui-on:text-*` shift ever
// reaches the glyph — ToggleGroup.vue bakes the fill per item from the `pressed`
// state, derived from the same `fg` string so the two can't drift.
export function iconFg(color: string, variant: Variant, on: boolean, isDark = false): IconFg {
  const { fg } = VARIANT_BUILDERS[variant](color)
  // on → the `group-ui-on:text-*` accent; off → the resting `text-*` token.
  const suffix = on
    ? fg.match(/\bgroup-ui-on:text-(\S+)/)?.[1]
    : fg.match(/^text-(\S+)/)?.[1]
  return iconFgFromToken(suffix, isDark)
}

export default (colors: Color[]) => ({
  slots: {
    // `root` direction is set per orientation variant (flex-row/flex-col).
    root: 'flex min-w-0 max-w-full',
    // `group` so children can read the item's `data-state` via `group-ui-on:*`.
    item: 'group flex flex-row items-center justify-center min-w-0 max-w-full font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-50',
    leadingIcon: 'shrink-0',
    label: 'truncate',
  },
  variants: {
    color: Object.fromEntries(colors.map(c => [c, ''])) as Record<Color, ''>,
    variant: Object.fromEntries(VARIANTS.map(v => [v, ''])) as Record<Variant, ''>,
    size: {
      sm: { item: 'px-2.5 py-1.5 text-sm gap-1.5', leadingIcon: 'size-5' },
      md: { item: 'px-3 py-2 text-sm gap-2', leadingIcon: 'size-5' },
      lg: { item: 'px-3 py-2 text-base gap-2', leadingIcon: 'size-6' },
      xl: { item: 'px-3.5 py-2.5 text-lg gap-2.5', leadingIcon: 'size-7' },
    },
    orientation: {
      horizontal: {
        root: 'flex-row flex-wrap -space-x-px',
        item: 'first:rounded-s-md last:rounded-e-md',
      },
      vertical: {
        root: 'flex-col -space-y-px',
        item: 'first:rounded-t-md last:rounded-b-md w-full',
      },
    },
  },
  compoundVariants: [
    // Surface lands on `item`; foreground color (`fg`) on `leadingIcon` +
    // `label`, which the item <view> won't cascade to.
    ...colors.flatMap(color =>
      VARIANTS.map((variant) => {
        const { base, fg } = VARIANT_BUILDERS[variant](color)
        return {
          color,
          variant,
          class: { item: base, leadingIcon: fg, label: fg },
        }
      }),
    ),
  ],
  defaultVariants: {
    color: 'primary' as const,
    variant: 'outline' as const,
    size: 'md' as const,
    orientation: 'horizontal' as const,
  },
})

// Bake-time icon-color resolution (shared by the button / tabs / toggleGroup
// themes).
//
// Lynx rasterizes each `<svg>`, so a `text-*` class on an icon slot never
// reaches the glyph — the fill is baked into the SVG via the Icon `color` prop
// (`resolveColorHex`). This maps the foreground CLASS a theme emits to a
// `{ semantic, shade }` descriptor for that resolver.
//
// Accent classes (`text-primary-600`) are mode-independent — the accent ramps
// don't invert. Semantic TOKENS (`text-muted`, …) resolve to different neutral
// shades in light vs dark, so callers pass the live `isDark` and the baked fill
// tracks the mode the way the CSS token would.

export type IconFg = { semantic: string, shade: number } | 'white'

const N = (shade: number): IconFg => ({ semantic: 'neutral', shade })

// suffix (the part after `text-`) → per-mode neutral fill. Mirrors the
// `--ui-text-*` values in `style.css` (light `:root`, dark `.dark`).
const SEMANTIC_TOKEN: Record<string, { light: IconFg, dark: IconFg }> = {
  highlighted: { light: N(900), dark: 'white' },
  default: { light: N(700), dark: N(200) },
  toned: { light: N(600), dark: N(300) },
  muted: { light: N(500), dark: N(400) },
  dimmed: { light: N(400), dark: N(500) },
  inverted: { light: 'white', dark: N(900) },
}

/**
 * Resolve an icon fill from a foreground class SUFFIX (the token after `text-`),
 * mode-aware. Returns `'white'` for `text-white`, unknown suffixes, and the
 * token ends that are white in `isDark`.
 */
export function iconFgFromToken(suffix: string | undefined, isDark: boolean): IconFg {
  if (!suffix || suffix === 'white')
    return 'white'
  // accent ramp: `{color}-{shade}` (ramp not inverted → mode-independent)
  const accent = suffix.match(/^([a-z]+)-(\d+)$/)
  if (accent)
    return { semantic: accent[1], shade: Number(accent[2]) }
  const token = SEMANTIC_TOKEN[suffix]
  return token ? token[isDark ? 'dark' : 'light'] : 'white'
}
